orders = list_orders('C-8254')
order_details = []
for order_id in orders:
    order = get_order(order_id)
    order_details.append(order)
skus = list(set([order['sku'] for order in order_details]))
prices = {}
for sku in skus:
    prices[sku] = get_price(sku)['unit_price_cents']
total = 0
for order in order_details:
    total += order['qty'] * prices[order['sku']]
print(total)

